/* @lc app=leetcode id=2192 lang=kotlin */
class Solution { fun getAncestors(n: Int, edges: Array<IntArray>): List<List<Int>> = Array(n) { mutableListOf<Int>() }.apply { edges.forEach { this[it[0]].add(it[1]) } }.let { adj -> Array(n) { sortedSetOf<Int>() }.apply { (0 until n).forEach { i -> java.util.ArrayDeque<Int>().apply { add(i) }.let { q -> BooleanArray(n).apply { this[i] = true }.let { vis -> while (q.isNotEmpty()) q.poll()?.let { curr -> adj[curr].forEach { next -> if (!vis[next]) vis[next].also { vis[next] = true }.also { this@apply[next].add(i) }.also { q.add(next) } } } } } } }.map { it.toList() } } }